            for a, b in (("x", "y"), ("col", "row"), ("cx", "cy")):
                if a in v and b in v:
                    return [v[a], v[b]]
            for k in ("pos", "position", "loc", "location"):
                if k in v:
                    p = pos(v[k])
                    if p is not None:
                        return p
        if isinstance(v, (list, tuple)) and len(v) >= 2 and isinstance(v[0], (int, float)) and isinstance(v[1], (int, float)):
            return [v[0], v[1]]
        return None

    s = pos(observation.get("self_position"))
    o = pos(observation.get("opponent_position"))
    if s is None:
        return [0, 0]

    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)
    obstacles = set()
    for x in observation.get("obstacles", []) or []:
        p = pos(x)
        if p is not None:
            obstacles.add((p[0], p[1]))

    best = None
    best_d = None
    for r in observation.get("resources", []) or []:
        p = pos(r)
        if p is None:
            continue
        d = abs(p[0] - s[0]) + abs(p[1] - s[1])
        if best_d is None or d < best_d:
            best_d, best = d, p

    moves = [(1,0), (-1,0), (0,1), (0,-1), (0,0)]
    if best is None:
        cand = [m for m in moves if (s[0]+m[0], s[1]+m[1]) not in obstacles]
        if o is not None:
            cand.sort(key=lambda m: abs((s[0]+m[0]) - o[0]) + abs((s[1]+m[1]) - o[1]), reverse=True)
        return list(cand[0]) if cand else [0, 0]

    def score(m):
        nx, ny = s[0] + m[0], s[1] + m[1]
        if (nx, ny) in obstacles:
            return -10**9
        if w and (nx < 0 or nx >= w): return -10**9
        if h and (ny < 0 or ny >= h): return -10**9
        d = abs(nx - best[0]) + abs(ny - best[1])
        if o is not None:
            d2 = abs(nx - o[0]) + abs(ny - o[1])
        else:
            d2 = 0
        return -d * 10 + d2

